#!/usr/bin/env python3
"""Collect exact bundled editable package files for source evidence."""
import hashlib
import json
from pathlib import Path
import shutil
import subprocess
import sys
import tarfile

PACKAGES = [
    ('certifi', '2026.10.19', 'certifi', 'certifi-2026.10.19.dist-info'),
    ('tqdm', '4.70.1', 'tqdm', 'tqdm-4.70.1.dist-info'),
    ('autocommand', '2.2.2', 'setuptools/_vendor/autocommand', 'setuptools/_vendor/autocommand-2.2.2.dist-info'),
]


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def collect(site, out):
    if out.exists():
        raise ValueError('output exists')
    out.mkdir(parents=True)
    rows = []
    for name, version, source, info in PACKAGES:
        row = {'name': name, 'version': version, 'files': []}
        for prefix in (source, info):
            src = site / prefix
            if not src.is_dir():
                raise ValueError(f'missing {src}')
            for path in sorted(src.rglob('*')):
                if path.is_symlink():
                    raise ValueError(f'unexpected symlink {path}')
                if not path.is_file() or '__pycache__' in path.parts or path.suffix == '.pyc':
                    continue
                relative = path.relative_to(site)
                dst = out / 'site-packages' / relative
                dst.parent.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(path, dst)
                row['files'].append({'path': str(dst.relative_to(out)), 'sha256': sha(dst), 'bytes': dst.stat().st_size})
        rows.append(row)
    app = site.parents[5]
    signature = subprocess.run(['/usr/bin/codesign', '-d', '--verbose=4', str(app)], capture_output=True, text=True, check=True)
    cdhash = next((line.partition('=')[2].strip() for line in (signature.stdout + '\n' + signature.stderr).splitlines() if line.startswith('CDHash=')), None)
    if not cdhash:
        raise ValueError('signed app CDHash missing')
    app_manifest = app / 'Contents/Resources/build-manifest.json'
    (out / 'manifest.json').write_text(json.dumps({'schema_version': 1, 'packages': rows,
        'source_app_cdhash': cdhash, 'source_app_build_manifest_sha256': sha(app_manifest),
        'scope': 'Files copied byte-for-byte from the existing app. Upstream release/source correspondence and complete distribution compliance are not asserted.'}, indent=2) + '\n')
    return rows


def archive(root, destination):
    if destination.exists():
        raise ValueError('archive exists')
    with tarfile.open(destination, 'x') as tar:
        for p in sorted(root.rglob('*')):
            if p.is_file():
                tar.add(p, arcname=p.relative_to(root), recursive=False)
    return sha(destination)


if __name__ == '__main__':
    src, output, target = map(Path, sys.argv[1:4])
    collect(src, output)
    (output / 'README.txt').write_text('''Editable source evidence copied from the existing Clippie app.\n\nThe site-packages tree preserves the app paths for certifi, tqdm and vendored autocommand, with their metadata, license texts and complete non-bytecode package files. manifest.json lists every included file and SHA256; the files were copied byte-for-byte and no modifications were made during collection. The vendored autocommand code is under setuptools/_vendor. Distribution metadata is included; generated bytecode is excluded. This is evidence of shipped files, not a full upstream source distribution or a legal clearance.\n\nTo study or modify, extract the archive and edit the Python files in the preserved site-packages tree. To produce a usable altered app, incorporate the edited files in the corresponding private runtime, repackage and re-sign the app, preserve the included licenses, and perform the applicable notice/source and relinking review. Rebuilding the full application additionally requires its own source, dependencies, packaging tools and the corresponding build configuration. This archive does not establish those requirements are complete.\n''')
    print(archive(output, target))
